<template>
  <main class="journal-page service-page"><header class="journal-top"><router-link :to="'/clubs/'+clubId+'/news'" aria-label="返回跑团资讯">‹</router-link><span>跑团内容发布</span><span class="top-spacer" aria-hidden="true"></span></header><section class="journal-editor"><h1>发布跑团资讯</h1><p>团练心得、赛事回顾，或一篇值得分享的公众号文章。</p><p v-if="message" role="alert" class="err">{{ message }}</p><p v-if="success" role="status" class="editor-notice">{{ success }}</p><div v-if="!allowed" class="journal-state">{{ loading ? '正在检查发布权限…' : '仅跑团团长与管理员可以发布资讯。' }}</div><template v-else><div class="editor-actions"><button type="button" @click="reset" :disabled="saving">＋ 新建一篇</button></div><form @submit.prevent="save('published')"><label>标题<input v-model="draft.title" maxlength="80" required placeholder="给故事起个名字" /></label><label>内容类型<select v-model="draft.rights"><option value="original">原创文章</option><option value="authorized">已获授权转载</option><option value="link">公众号 / 原文推荐</option></select></label><label>摘要<textarea v-model="draft.summary" maxlength="400" rows="3" placeholder="用几句话介绍这篇内容"></textarea></label><label v-if="draft.rights !== 'link'">正文<textarea v-model="draft.body" maxlength="20000" rows="12" placeholder="支持 Markdown 标题与段落"></textarea></label><label>来源名称<input v-model="draft.source" maxlength="80" required placeholder="跑团名或公众号名称" /></label><label>原文链接<input v-model="draft.sourceUrl" type="url" maxlength="2000" :required="draft.rights !== 'original'" placeholder="https://mp.weixin.qq.com/s/..." /></label><p v-if="draft.rights === 'link'" class="editor-notice">推荐文章展示标题、摘要和原文入口。小程序支持点击打开公众号原文。</p><div class="editor-actions"><button class="editor-primary" type="submit" :disabled="saving">{{ saving ? '保存中…' : '发布文章' }}</button><button type="button" :disabled="saving" @click="save('draft')">保存草稿</button><button v-if="draft.id" type="button" :disabled="saving" @click="save('archived')">下架</button><button type="button" @click="preview = !preview">{{ preview ? '收起预览' : '预览内容' }}</button></div></form><article v-if="preview" class="editor-preview"><h2>{{ draft.title || '未填写标题' }}</h2><p>{{ draft.summary }}</p><p v-for="b in previewBlocks" :key="b.i"><span v-if="b.mark">{{b.mark}} </span><template v-for="r in b.runs" :key="r.j"><strong v-if="r.strong">{{r.text}}</strong><template v-else>{{r.text}}</template></template></p><small>{{ draft.source }}</small></article><div class="editor-list"><h2>已保存的内容</h2><button v-for="row in rows" :key="row.id" type="button" @click="edit(row)" :disabled="saving"><span>{{ row.title }}</span><small>{{ statusName(row.status) }} ›</small></button><p v-if="!rows.length">还没有文章，先保存第一篇。</p><Pager :page="page" :pages="pages" @update:page="turnPage" /></div></template></section></main>
</template>
<script setup>
import {computed,onBeforeUnmount,onMounted,ref} from 'vue';
import {useRoute} from 'vue-router';
import {api} from '../api';
import {parseGuide} from '../guide-md';
import Pager from '../components/Pager.vue';
const route=useRoute(),clubId=route.params.id;
const allowed=ref(false),loading=ref(true),rows=ref([]),message=ref(''),success=ref(''),saving=ref(false),clubName=ref(''),page=ref(1),pages=ref(1),preview=ref(false);
const blank=()=>({title:'',summary:'',body:'',rights:'original',source:clubName.value,sourceUrl:'',category:'club'}),draft=ref(blank());
const previewBlocks=computed(()=>parseGuide(draft.value.rights==='link'?'':draft.value.body));
let epoch=0,listTicket=0,editTicket=0,permissionTicket=0,disposed=false,account=localStorage.getItem('marathon_token')||'';
const scope=()=>({epoch,account});
const current=s=>!disposed&&s.epoch===epoch&&s.account===(localStorage.getItem('marathon_token')||'');
function invalidate(text){epoch++;listTicket++;editTicket++;allowed.value=false;rows.value=[];clubName.value='';draft.value=blank();page.value=1;pages.value=1;preview.value=false;saving.value=false;success.value='';message.value=text||'';}
function statusName(s){return({published:'已发布',draft:'草稿',archived:'已下架'})[s]||s;}
function reset(){if(saving.value||!allowed.value)return;editTicket++;draft.value=blank();success.value='';message.value='';preview.value=false;}
async function load(){const token=scope(),ticket=++listTicket;const d=await api('/clubs/'+clubId+'/content/articles?page='+page.value);if(!current(token)||ticket!==listTicket)return;rows.value=d.articles||[];pages.value=d.pages||1;page.value=d.page||1;}
function handleError(e){if(e.status===401||e.status===403)invalidate(e.message);else message.value=e.message;}
async function turnPage(p){if(saving.value)return;page.value=p;try{await load();}catch(e){handleError(e);}}
async function edit(r){if(saving.value||!allowed.value)return;message.value='';success.value='';const token=scope(),ticket=++editTicket;try{const d=await api('/clubs/'+clubId+'/content/articles/'+r.id);if(!current(token)||ticket!==editTicket)return;draft.value={...d.article};window.scrollTo({top:0,behavior:'smooth'});}catch(e){if(current(token)&&ticket===editTicket)handleError(e);}}
async function save(status){if(saving.value||!allowed.value)return;const token=scope();if(!current(token)){invalidate('登录账号已变化，请重新打开发布页。');return;}editTicket++;message.value='';success.value='';saving.value=true;try{const d=await api('/clubs/'+clubId+'/content/articles'+(draft.value.id?'/'+draft.value.id:''),{method:draft.value.id?'PUT':'POST',body:JSON.stringify({...draft.value,body:draft.value.rights==='link'?'':draft.value.body,category:'club',status})});if(!current(token))return;draft.value={...d.article};success.value=status==='published'?'已发布，可在跑团资讯与跑圈资讯查看。':status==='draft'?'草稿已保存，仅管理人员可见。':'文章已下架。';await load();}catch(e){if(current(token))handleError(e);}finally{if(current(token))saving.value=false;}}
async function checkPermission(){const fresh=localStorage.getItem('marathon_token')||'';if(fresh!==account){invalidate();account=fresh;}if(!account){invalidate('请先登录，再管理跑团资讯。');loading.value=false;return;}const token=scope(),ticket=++permissionTicket;loading.value=true;allowed.value=false;try{const c=await api('/clubs/'+clubId);if(!current(token)||ticket!==permissionTicket)return;if(!c.club?.staff){invalidate('仅跑团团长与管理员可以发布资讯。');return;}allowed.value=true;clubName.value=c.club.name||'';if(!draft.value.id&&!draft.value.source)draft.value.source=clubName.value;await load();}catch(e){if(current(token)&&ticket===permissionTicket)handleError(e);}finally{if(!disposed&&ticket===permissionTicket)loading.value=false;}}
function sessionChanged(){if(document.visibilityState==='hidden')return;checkPermission();}
onMounted(()=>{window.addEventListener('storage',sessionChanged);window.addEventListener('focus',sessionChanged);document.addEventListener('visibilitychange',sessionChanged);checkPermission();});
onBeforeUnmount(()=>{disposed=true;epoch++;window.removeEventListener('storage',sessionChanged);window.removeEventListener('focus',sessionChanged);document.removeEventListener('visibilitychange',sessionChanged);});
</script>
<style scoped src="../journal.css"></style>

<style scoped src="../service-ui.css"></style>
